import http from 'node:http';
import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const defaultDataFile = path.join(root, 'data', 'books.json');
const publicDir = path.join(root, 'public');
const assets = {
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
};

function reply(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

async function readBooks(file) {
  try {
    const books = JSON.parse(await readFile(file, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(file, books) {
  await mkdir(path.dirname(file), { recursive: true });
  const temporaryFile = `${file}.${randomUUID()}.tmp`;
  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`);
  await rename(temporaryFile, file);
}

async function readJson(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 1_000_000) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(text);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

function cleanText(value, max) {
  return typeof value === 'string' ? value.trim().slice(0, max) : '';
}

export function createApp({ dataFile = defaultDataFile } = {}) {
  // Serialize mutations so concurrent requests cannot overwrite one another.
  let pending = Promise.resolve();
  function mutate(change) {
    const operation = pending.then(async () => {
      const books = await readBooks(dataFile);
      const result = change(books);
      if (result.changed) await saveBooks(dataFile, books);
      return result;
    });
    pending = operation.catch(() => {});
    return operation;
  }

  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      const pathname = url.pathname;
      if (pathname === '/api/books' && req.method === 'GET') {
        await pending;
        return reply(res, 200, await readBooks(dataFile));
      }
      if (pathname === '/api/books' && req.method === 'POST') {
        const input = await readJson(req);
        const title = cleanText(input?.title, 160);
        const author = cleanText(input?.author, 120);
        const notes = cleanText(input?.notes, 5000);
        if (!title || !author || !['reading', 'finished'].includes(input?.status)) {
          return reply(res, 400, { error: 'Title, author, and a valid status are required.' });
        }
        const result = await mutate(books => {
          const book = { id: randomUUID(), title, author, notes, status: input.status, addedAt: new Date().toISOString(), finishedAt: input.status === 'finished' ? new Date().toISOString() : null };
          books.unshift(book);
          return { changed: true, book };
        });
        return reply(res, 201, result.book);
      }
      const match = pathname.match(/^\/api\/books\/([0-9a-f-]{36})(?:\/(finish))?$/i);
      if (match) {
        const [, id, action] = match;
        if (req.method === 'GET' && !action) {
          await pending;
          const book = (await readBooks(dataFile)).find(item => item.id === id);
          return reply(res, book ? 200 : 404, book || { error: 'Book not found.' });
        }
        if (req.method === 'PATCH' && action === 'finish') {
          const result = await mutate(books => {
            const book = books.find(item => item.id === id);
            if (!book) return { changed: false, book: null };
            if (book.status !== 'finished') {
              book.status = 'finished';
              book.finishedAt = new Date().toISOString();
              return { changed: true, book };
            }
            return { changed: false, book };
          });
          return reply(res, result.book ? 200 : 404, result.book || { error: 'Book not found.' });
        }
        if (req.method === 'DELETE' && !action) {
          const result = await mutate(books => {
            const index = books.findIndex(item => item.id === id);
            if (index === -1) return { changed: false };
            books.splice(index, 1);
            return { changed: true };
          });
          return reply(res, result.changed ? 200 : 404, result.changed ? { ok: true } : { error: 'Book not found.' });
        }
      }
      if (req.method === 'GET' && (assets[pathname] || /^\/books\/[0-9a-f-]{36}\/?$/i.test(pathname))) {
        const [file, type] = assets[pathname] || assets['/'];
        return reply(res, 200, await readFile(path.join(publicDir, file)), type);
      }
      return reply(res, 404, { error: 'Not found.' });
    } catch (error) {
      console.error(error);
      return reply(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong reading the library.' });
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => console.log(`Reading Room is open at http://localhost:${port}`));
}

