@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap');

:root{--forest:#273e35;--forest-dark:#20362e;--ink:#25342e;--muted:#79847a;--line:#e4e6df;--paper:#f7f8f4;--white:#fff;--accent:#b97558;--serif:'DM Serif Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}
button,input,textarea{font:inherit}
button{cursor:pointer}
a{color:inherit;text-decoration:none}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #bd9274;outline-offset:3px}
.app-shell{min-height:100vh;display:flex}
.sidebar{width:240px;flex:none;min-height:100vh;position:sticky;top:0;height:100vh;background:var(--forest);color:#fff;display:flex;flex-direction:column;padding:39px 18px 29px;overflow:auto}
.brand{display:flex;align-items:center;gap:14px;margin:0 13px 73px;width:max-content}
.brand__mark{width:35px;height:38px;display:flex;gap:3px;align-items:flex-end;transform:rotate(-7deg)}
.brand__mark span{display:block;height:31px;width:9px;border:1.6px solid #e9e7d4;border-radius:1px}.brand__mark span:nth-child(2){height:36px;background:#c78466;border-color:#c78466}.brand__mark span:nth-child(3){height:29px}
.brand__name{font:24px/.86 var(--serif);letter-spacing:-.5px}.brand__name i{font-weight:400;color:#d0a58d}
.sidebar__label{color:#9baea1;font-size:10px;letter-spacing:2px;font-weight:700;margin:0 17px 19px}
.nav{display:grid;gap:5px}.nav__link{display:flex;align-items:center;gap:13px;min-height:45px;padding:0 14px;color:#c6d1c9;font-size:12px;font-weight:600;border-radius:8px;white-space:nowrap;transition:background .2s,color .2s}.nav__link:hover,.nav__link--active{color:#fff;background:#3a5347}.nav__link svg{width:17px;height:17px;flex:none;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.nav__count{margin-left:auto;color:#b5c6b8;font-size:11px}
.sidebar__bottom{margin:auto 15px 0;padding-top:55px}.sidebar__ornament{font:36px var(--serif);color:#d5a47e;margin-bottom:11px}.sidebar__bottom p{font:italic 19px/1.34 var(--serif);letter-spacing:.1px;margin:0 0 35px;color:#eef0e7}.sidebar__bottom>span{font-size:9px;letter-spacing:1.8px;color:#9ab09f;font-weight:700}
.main{flex:1;min-width:0}.main__inner{max-width:1390px;min-height:100vh;padding:0 clamp(30px,5.1vw,86px);margin:auto;display:flex;flex-direction:column}.topbar{height:110px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.topbar__location{font-size:10px;font-weight:700;letter-spacing:2.1px;color:#737f73;display:flex;align-items:center;gap:11px}.topbar__dot{width:7px;height:7px;border-radius:50%;background:#b98265}.mobile-brand{display:none}
.button{border:0;display:inline-flex;align-items:center;justify-content:center;gap:11px;border-radius:7px;padding:13px 20px;font-size:12px;font-weight:700;letter-spacing:.1px;transition:transform .2s,background .2s,box-shadow .2s}.button:hover{transform:translateY(-2px)}.button--dark{background:var(--forest);color:white;box-shadow:0 4px 10px #253f3214}.button--dark:hover{background:#37594a}.button--outline{background:transparent;color:var(--forest);border:1px solid #cfd9cf}.button--outline:hover{background:#f1f6f0}.button--full{width:100%;justify-content:space-between;padding:16px 18px}.button__plus{font-size:20px;font-weight:400;line-height:12px;margin-top:-2px}
#content{flex:1}.intro{padding:52px 0 37px;display:flex;align-items:flex-end;justify-content:space-between;gap:35px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2.2px;color:#ac785e;text-transform:uppercase}.intro h1,.detail-intro h1{font:normal clamp(42px,4.25vw,64px)/1.04 var(--serif);letter-spacing:-1.7px;margin:15px 0 17px;color:var(--forest)}.intro h1 em,.detail-intro h1 em{font-weight:400;color:#a8745d}.intro p{color:#778379;font-size:14px;line-height:1.65;margin:0;max-width:570px}.shelf-total{min-width:159px;border-left:1px solid #d8ddd6;padding:5px 0 5px 25px;margin-bottom:4px}.shelf-total strong{display:block;font:normal 36px/1 var(--serif);color:var(--forest)}.shelf-total span{font-size:10px;font-weight:700;letter-spacing:1.2px;color:#819083;display:block;margin-top:9px}
.section{padding:12px 0 38px;scroll-margin-top:30px}.section--finished{border-top:1px solid var(--line);padding-top:30px;padding-bottom:62px}.section__header{display:flex;align-items:center;gap:13px;margin-bottom:19px}.section__header h2{font:normal 27px/1.2 var(--serif);margin:0;letter-spacing:-.35px;color:var(--forest)}.section__header .section__count{background:#e6ebe4;color:#607164;border-radius:99px;padding:4px 9px;font-size:10px;font-weight:700}.section__header .section__aside{font-size:11px;color:#9ba59a;margin-left:auto}.books-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.books-grid--finished{grid-template-columns:repeat(3,minmax(0,1fr))}
.book-card{background:#fff;border:1px solid #e9ece6;border-radius:10px;min-width:0;box-shadow:0 7px 25px #293e2c07;transition:transform .2s,box-shadow .2s,border-color .2s;position:relative}.book-card:hover{transform:translateY(-3px);box-shadow:0 14px 28px #293e2c12;border-color:#d7e0d5}.book-card__link{display:flex;gap:23px;padding:20px;min-height:238px}.book-card__text{min-width:0;display:flex;flex-direction:column;padding:4px 0 3px;flex:1}.status-tag{display:inline-flex;align-items:center;gap:6px;width:max-content;background:#eaf1e8;color:#55765f;padding:6px 8px;border-radius:4px;font-size:9px;letter-spacing:.65px;font-weight:700;text-transform:uppercase}.status-tag:before{content:'';display:block;width:5px;height:5px;border-radius:50%;background:#79a786}.status-tag--finished{background:#f3eee8;color:#a5775c}.status-tag--finished:before{background:#bd8a6a}.book-card h3{font:normal clamp(20px,2vw,25px)/1.12 var(--serif);letter-spacing:-.25px;margin:15px 0 6px;color:var(--forest);overflow-wrap:anywhere}.book-card__author{font-size:12px;color:#7c897e;margin:0}.book-card__note{font-size:11px;line-height:1.5;color:#929e92;margin:auto 0 17px;padding-top:13px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.book-card__bottom{display:flex;align-items:center;gap:8px;padding-top:12px;border-top:1px solid #edf0eb;margin-top:auto;font-size:10px;font-weight:700;color:#789079}.book-card__bottom span{font-size:16px;font-weight:400}.book-card__action{position:absolute;bottom:20px;right:20px;border:0;background:#f2f5ef;color:#496750;border-radius:5px;padding:9px 10px;font-size:10px;font-weight:700;transition:background .2s}.book-card__action:hover{background:#dce9da}.book-card--reading .book-card__bottom{padding-right:105px}.book-card--reading .book-card__note{margin-bottom:12px}
.cover{--cover:#9c6457;--cover-ink:#f7e5d4;position:relative;flex:none;width:132px;height:195px;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;background:var(--cover);color:var(--cover-ink);border-radius:2px 5px 5px 2px;box-shadow:inset 6px 0 10px #221f1d2a,inset -2px 0 4px #ffffff21,7px 9px 13px #292b2425;overflow:hidden;padding:17px 15px 14px 19px}.cover:before{content:'';position:absolute;left:8px;top:0;bottom:0;border-left:1px solid #ffffff35}.cover:after{content:'';width:106px;height:106px;border:1px solid currentColor;opacity:.23;border-radius:50%;position:absolute;right:-48px;bottom:21px;pointer-events:none}.cover__top{font:700 7px/1.3 var(--sans);letter-spacing:1.6px;opacity:.85}.cover__center{font:normal 18px/1.03 var(--serif);overflow-wrap:anywhere;position:relative;z-index:1;max-height:112px;overflow:hidden}.cover__author{font-size:8px;line-height:1.25;letter-spacing:.2px;position:relative;z-index:1}.cover--0{--cover:#b46e54;--cover-ink:#fff4e8}.cover--1{--cover:#6b877b;--cover-ink:#f4f2d9}.cover--2{--cover:#777586;--cover-ink:#f5e9dc}.cover--3{--cover:#c89b70;--cover-ink:#3d4a39}.cover--4{--cover:#4d6979;--cover-ink:#f0e9d6}.cover--5{--cover:#9f847c;--cover-ink:#fff0dd}
.book-card--finished .book-card__link{padding:17px;gap:16px;min-height:155px}.book-card--finished .cover{width:87px;height:123px;padding:12px 8px 10px 13px}.book-card--finished .cover__top{font-size:5px;letter-spacing:1px}.book-card--finished .cover__center{font-size:12px;max-height:67px}.book-card--finished .cover__author{font-size:6px}.book-card--finished .cover:after{width:75px;height:75px;right:-38px}.book-card--finished .book-card__text{padding:1px 0}.book-card--finished h3{font-size:19px;line-height:1.14;margin:12px 0 5px}.book-card--finished .book-card__bottom{font-size:10px;margin-top:auto;padding-top:8px}.book-card--finished .status-tag{padding:5px 7px}
.empty-state{background:white;border:1px dashed #cdd8ca;border-radius:10px;padding:32px;display:flex;align-items:center;justify-content:space-between;gap:20px}.empty-state__symbol{font:32px var(--serif);color:#b77e61;margin-right:15px}.empty-state strong{font:normal 19px var(--serif);color:var(--forest)}.empty-state p{margin:5px 0 0;font-size:12px;color:#89978a}
