const content = document.querySelector('#content');
const dialog = document.querySelector('#add-dialog');
const form = document.querySelector('#add-form');
const toast = document.querySelector('#toast');
let toastTimer;

function escapeHtml(value = '') {
  return String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

async function api(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong. Please try again.');
  return data;
}

function notify(message) {
  toast.textContent = message;
  toast.classList.add('toast--visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('toast--visible'), 3200);
}

function cover(book, large = false) {
  const tone = [...book.title].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 6;
  return `<div class="cover cover--${tone}${large ? ' cover--large' : ''}" aria-hidden="true"><span class="cover__top">READING ROOM · VOL. 01</span><span class="cover__center">${escapeHtml(book.title)}</span><span class="cover__author">${escapeHtml(book.author)}</span></div>`;
}

function card(book) {
  const finished = book.status === 'finished';
  return `<article class="book-card book-card--${finished ? 'finished' : 'reading'}">
    <a href="/books/${encodeURIComponent(book.id)}" class="book-card__link" aria-label="View ${escapeHtml(book.title)} by ${escapeHtml(book.author)}">
      ${cover(book)}
      <div class="book-card__text">
        <span class="status-tag ${finished ? 'status-tag--finished' : ''}">${finished ? 'Finished' : 'In progress'}</span>
        <h3>${escapeHtml(book.title)}</h3>
        <p class="book-card__author">by ${escapeHtml(book.author)}</p>
        ${!finished && book.notes ? `<p class="book-card__note">“${escapeHtml(book.notes)}”</p>` : ''}
        <span class="book-card__bottom">View book <span aria-hidden="true">↗</span></span>
      </div>
    </a>
    ${finished ? '' : `<button class="book-card__action" type="button" data-action="finish" data-id="${escapeHtml(book.id)}" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark finished</button>`}
  </article>`;
}

function emptyState(finished) {
  return `<div class="empty-state"><div style="display:flex;align-items:center"><span class="empty-state__symbol" aria-hidden="true">✳</span><div><strong>${finished ? 'A fresh chapter.' : 'Your next story starts here.'}</strong><p>${finished ? 'Books you finish will find their home on this shelf.' : 'Add a book to start filling up your reading shelf.'}</p></div></div>${finished ? '' : '<button type="button" class="button button--outline" data-action="add">Add a book</button>'}</div>`;
}

function renderHome(books) {
  const reading = books.filter(book => book.status === 'reading').sort((a, b) => (b.addedAt || '').localeCompare(a.addedAt || ''));
  const finished = books.filter(book => book.status === 'finished').sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));
  document.querySelector('#reading-nav-count').textContent = reading.length;
  document.querySelector('#finished-nav-count').textContent = finished.length;
  document.title = 'Reading Room — Your personal bookshelf';
  content.innerHTML = `<div class="intro"><div><div class="eyebrow">A HOME FOR YOUR STORIES</div><h1>Your reading <em>room.</em></h1><p>All the stories you're in the middle of, and the ones you'll carry with you.</p></div><div class="shelf-total"><strong>${books.length.toString().padStart(2, '0')}</strong><span>BOOKS ON YOUR SHELF</span></div></div>
    <section class="section" id="reading" aria-labelledby="reading-title"><div class="section__header"><h2 id="reading-title">Currently reading</h2><span class="section__count">${reading.length}</span><span class="section__aside">The stories unfolding now</span></div>${reading.length ? `<div class="books-grid">${reading.map(card).join('')}</div>` : emptyState(false)}</section>
    <section class="section section--finished" id="finished" aria-labelledby="finished-title"><div class="section__header"><h2 id="finished-title">Finished &amp; loved</h2><span class="section__count">${finished.length}</span><span class="section__aside">Stories that stayed with you</span></div>${finished.length ? `<div class="books-grid books-grid--finished">${finished.map(card).join('')}</div>` : emptyState(true)}</section>`;
  if (location.hash) requestAnimationFrame(() => document.querySelector(location.hash)?.scrollIntoView());
}

function formatDate(date) {
  if (!date) return '—';
  const parsed = new Date(date);
  return Number.isNaN(parsed.valueOf()) ? '—' : parsed.toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' });
}

function renderDetail(book) {
  document.title = `${book.title} — Reading Room`;
  const finished = book.status === 'finished';
  content.innerHTML = `<div class="detail-breadcrumb"><a href="/">Your shelf</a><span aria-hidden="true">/</span><span>Book details</span></div>
    <div class="detail-intro"><div class="eyebrow">A STORY ON YOUR SHELF</div><h1>${escapeHtml(book.title)}<em>.</em></h1><p>by ${escapeHtml(book.author)}</p></div>
    <div class="detail-layout"><div class="detail-cover-panel">${cover(book, true)}</div>
      <div class="detail-body"><div class="detail-panel"><div class="detail-panel__heading">YOUR NOTES</div><p class="detail-panel__notes ${book.notes ? '' : 'detail-panel__notes--empty'}">${book.notes ? escapeHtml(book.notes) : 'No notes yet for this book.'}</p></div>
      <div class="detail-panel"><div class="detail-panel__heading">ON THE SHELF</div><div class="detail-meta"><div><span>Status</span><strong>${finished ? 'Finished' : 'Currently reading'}</strong></div><div><span>Added</span><strong>${formatDate(book.addedAt)}</strong></div>${finished ? `<div><span>Finished</span><strong>${formatDate(book.finishedAt)}</strong></div>` : ''}</div></div>
      <div class="detail-actions"><button type="button" class="button button--dark" data-action="share">Copy book link <span aria-hidden="true">↗</span></button>${finished ? '' : `<button type="button" class="button button--outline" data-action="finish" data-id="${escapeHtml(book.id)}">Mark as finished</button>`}<button type="button" class="delete-button" data-action="delete" data-id="${escapeHtml(book.id)}">Remove book</button></div></div></div>`;
}

function renderMissing() {
  document.title = 'Book not found — Reading Room';
  content.innerHTML = '<div class="detail-not-found"><div class="eyebrow">NOT ON THIS SHELF</div><h1>Book not found.</h1><p>This book may have been removed, or the link might be incorrect.</p><a class="button button--dark" href="/">Back to your shelf</a></div>';
}

async function load() {
  content.innerHTML = '<div class="intro"><div><div class="eyebrow">OPENING YOUR LIBRARY</div><h1>Just a moment<em>.</em></h1></div></div>';
  try {
    const id = location.pathname.match(/^\/books\/([0-9a-f-]{36})\/?$/i)?.[1];
    if (id) {
      try { renderDetail(await api(`/api/books/${id}`)); }
      catch (error) { if (error.message === 'Book not found.') renderMissing(); else throw error; }
    } else {
      renderHome(await api('/api/books'));
    }
  } catch (error) {
    content.innerHTML = `<div class="detail-not-found"><h1>Couldn't open your library.</h1><p>${escapeHtml(error.message)}</p><button type="button" class="button button--dark" data-action="retry">Try again</button></div>`;
  }
}

function openDialog() {
  form.reset();
  document.querySelector('#form-error').hidden = true;
  dialog.showModal();
  document.querySelector('#book-title').focus();
}

document.querySelector('#open-add').addEventListener('click', openDialog);
document.querySelector('#close-add').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });

form.addEventListener('submit', async event => {
  event.preventDefault();
  const button = document.querySelector('#save-book');
  const errorElement = document.querySelector('#form-error');
  button.disabled = true;
  button.textContent = 'Adding to your shelf...';
  errorElement.hidden = true;
  try {
    const fields = new FormData(form);
    const book = await api('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(fields)) });
    location.href = `/books/${book.id}`;
  } catch (error) {
    errorElement.textContent = error.message;
    errorElement.hidden = false;
    button.disabled = false;
    button.innerHTML = 'Add to my shelf <span aria-hidden="true">↗</span>';
  }
});

content.addEventListener('click', async event => {
  const button = event.target.closest('button[data-action]');
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === 'add') return openDialog();
  if (action === 'retry') return load();
  if (action === 'share') {
    try {
      await navigator.clipboard.writeText(location.href);
      notify('Book link copied to clipboard.');
    } catch {
      window.prompt('Copy this book link:', location.href);
    }
    return;
  }
  if (action === 'delete' && !window.confirm('Remove this book from your shelf? This cannot be undone.')) return;
  button.disabled = true;
  try {
    if (action === 'finish') {
      await api(`/api/books/${id}/finish`, { method: 'PATCH' });
      await load();
      notify('Moved to your finished shelf.');
    } else if (action === 'delete') {
      await api(`/api/books/${id}`, { method: 'DELETE' });
      location.href = '/';
    }
  } catch (error) {
    notify(error.message);
    button.disabled = false;
  }
});

load();

