import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createApp } from '../server.js';

async function listen(server) {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return `http://127.0.0.1:${server.address().port}`;
}

async function close(server) {
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}

test('books can be added, viewed by shareable URL, finished, and persisted after restart', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'reading-room-'));
  const dataFile = path.join(directory, 'books.json');
  let server = createApp({ dataFile });
  try {
    let base = await listen(server);
    let response = await fetch(`${base}/api/books`);
    assert.deepEqual(await response.json(), []);

    response = await fetch(`${base}/api/books`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: '  The Left Hand of Darkness  ', author: '  Ursula K. Le Guin ', notes: 'A note to remember.', status: 'reading' }),
    });
    assert.equal(response.status, 201);
    const book = await response.json();
    assert.equal(book.title, 'The Left Hand of Darkness');
    assert.equal(book.author, 'Ursula K. Le Guin');
    assert.equal(book.status, 'reading');

    response = await fetch(`${base}/books/${book.id}`);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /<div id="content"/);
    response = await fetch(`${base}/api/books/${book.id}`);
    assert.equal((await response.json()).notes, 'A note to remember.');

    response = await fetch(`${base}/api/books/${book.id}/finish`, { method: 'PATCH' });
    assert.equal(response.status, 200);
    assert.equal((await response.json()).status, 'finished');
    assert.equal(JSON.parse(await readFile(dataFile, 'utf8'))[0].status, 'finished');

    await close(server);
    server = createApp({ dataFile });
    base = await listen(server);
    response = await fetch(`${base}/api/books`);
    assert.equal((await response.json())[0].id, book.id);
    response = await fetch(`${base}/api/books/${book.id}`);
    assert.equal((await response.json()).finishedAt !== null, true);

    response = await fetch(`${base}/api/books/${book.id}`, { method: 'DELETE' });
    assert.equal(response.status, 200);
    response = await fetch(`${base}/api/books/${book.id}`);
    assert.equal(response.status, 404);
