test('concurrent additions are all kept in the JSON file', async () => {
  const directory = await mkdtemp(path.join(tmpdir(), 'reading-room-'));
  const dataFile = path.join(directory, 'books.json');
  const server = createApp({ dataFile });
  const base = await listen(server);
  try {
    const responses = await Promise.all(Array.from({ length: 8 }, (_, index) => fetch(`${base}/api/books`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: `Book ${index}`, author: 'An Author', status: 'reading' }),
    })));
    assert.ok(responses.every(response => response.status === 201));
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    assert.equal(books.length, 8);
    assert.equal(new Set(books.map(book => book.id)).size, 8);
  } finally {
    await close(server);
    await rm(directory, { recursive: true, force: true });
  }
});

